import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.TimeUnit;

BlockingQueue<Job> q = new ArrayBlockingQueue<>(256);   // bounded -> put blocks when full

// producer (owns termination; there is no close, so use a poison pill):
class POISON {} static final Job POISON = new POISON();
for (Job j : jobs) q.put(j);          // blocks when full (backpressure)
q.put(POISON);                        // sentinel: the consumer's take returns it and exits

// consumer:
while (true) {
    Job j = q.take();                  // blocks when empty; nullopt form:
    if (j instanceof POISON) break;
    process(j);
}

// non-blocking / timeout forms (the 'select'):
Job j = q.poll(2, TimeUnit.SECONDS);   // null on timeout = the select-with-timeout
